//! almondbread-ffi: the UniFFI surface of the Rust core for the Swift UI
//! (kb: decisions/rust-core, platform/rust-swift-ffi).
//!
//! Built as a static library into `AlmondbreadCoreFFI.xcframework`
//! (scripts/build-rust-xcframework.sh); the Swift bindings are generated by uniffi-bindgen
//! in library mode. Rule: nothing per pixel or per iteration crosses this boundary; bulk
//! data (orbits) moves as one copy into caller memory.
//!
//! - R1: version, coordinate parse/format, precision rule, reference selection, reference
//!   orbit with cancellation, and a no-op call for measuring the call overhead.
//! - R2b: the `Explorer` (explorer.rs, Apple targets): the renderer hosted in the app's
//!   `CAMetalLayer`, one `frame` call per display refresh; `palettes()`.

use almondbread_core::math::{self, BigComplex, BigFloat, FloatExpComplex};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};

uniffi::setup_scaffolding!();

#[cfg(target_vendor = "apple")]
mod explorer;

#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum CoreError {
    #[error("malformed number: {text}")]
    Malformed { text: String },
    #[error("invalid argument: {message}")]
    InvalidArgument { message: String },
    #[error("GPU: {message}")]
    Gpu { message: String },
}

fn invalid(message: impl Into<String>) -> CoreError {
    CoreError::InvalidArgument {
        message: message.into(),
    }
}

/// Upper bound on precision accepted over the FFI (bits); far beyond any real zoom.
const MAX_PRECISION_BITS: u32 = 1 << 20;
/// Upper bound on orbit length accepted over the FFI (points are 24 bytes each).
const MAX_ORBIT_ITERATIONS: u64 = 1 << 31;

fn check_bits(bits: u32) -> Result<usize, CoreError> {
    if bits == 0 || bits > MAX_PRECISION_BITS {
        return Err(invalid(format!(
            "precision_bits must be in 1...{MAX_PRECISION_BITS}, got {bits}"
        )));
    }
    Ok(bits as usize)
}

fn parse(text: &str, bits: usize) -> Result<BigFloat, CoreError> {
    BigFloat::parse(text, bits).ok_or_else(|| CoreError::Malformed { text: text.to_string() })
}

/// One colour stop of a palette: position in 0..1, sRGB `0xRRGGBB`.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct PaletteStop {
    pub position: f64,
    pub rgb: u32,
}

/// A palette as the inspector lists it (the gradient wraps from the last stop to the first).
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct PaletteInfo {
    pub id: String,
    pub name: String,
    pub stops: Vec<PaletteStop>,
}

/// The palettes, in menu order (the first is the default).
#[uniffi::export]
pub fn palettes() -> Vec<PaletteInfo> {
    almondbread_core::palette::Palette::all()
        .into_iter()
        .map(|p| PaletteInfo {
            id: p.id.to_string(),
            name: p.name.to_string(),
            stops: p
                .stops
                .iter()
                .map(|&(position, rgb)| PaletteStop { position, rgb })
                .collect(),
        })
        .collect()
}

/// "almondbread-core <version>".
#[uniffi::export]
pub fn core_version() -> String {
    format!("almondbread-core {}", env!("CARGO_PKG_VERSION"))
}

/// Returns x + 1. Exists to measure the bare FFI call overhead.
#[uniffi::export]
pub fn ping(x: u64) -> u64 {
    x.wrapping_add(1)
}

/// A complex coordinate as decimal strings (exact at their precision).
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct Coordinate {
    pub re: String,
    pub im: String,
}

/// Parses a coordinate at `precision_bits` and formats it back (`digits` significant
/// digits, or round-trip digits when absent). Correctly rounded both ways.
#[uniffi::export]
pub fn normalize_coordinate(
    re: String,
    im: String,
    precision_bits: u32,
    digits: Option<u32>,
) -> Result<Coordinate, CoreError> {
    let bits = check_bits(precision_bits)?;
    let d = digits.map(|d| d.max(1) as usize);
    Ok(Coordinate {
        re: parse(&re, bits)?.to_decimal_string(d),
        im: parse(&im, bits)?.to_decimal_string(d),
    })
}

/// Bits for a reference in a view with this pixel spacing (log2) and image size
/// (kb: techniques/reference-orbit-precision).
#[uniffi::export]
pub fn recommended_precision_bits(pixel_spacing_log2: f64, image_size: u32) -> u32 {
    math::recommended_precision_bits(pixel_spacing_log2, image_size as usize) as u32
}

/// A cancellation flag shared between Swift and a running Rust computation.
#[derive(uniffi::Object, Default)]
pub struct CancelToken {
    flag: AtomicBool,
    progress: AtomicU64,
}

#[uniffi::export]
impl CancelToken {
    #[uniffi::constructor]
    pub fn new() -> Arc<Self> {
        Arc::new(Self::default())
    }

    pub fn cancel(&self) {
        self.flag.store(true, Ordering::Relaxed);
    }

    pub fn is_cancelled(&self) -> bool {
        self.flag.load(Ordering::Relaxed)
    }

    /// Iterations done by the computation using this token (updated every 4096).
    pub fn progress(&self) -> u64 {
        self.progress.load(Ordering::Relaxed)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum PeriodMethod {
    Ball,
    BallFirstOrder,
    Box,
}

impl From<PeriodMethod> for math::PeriodMethod {
    fn from(m: PeriodMethod) -> Self {
        match m {
            PeriodMethod::Ball => math::PeriodMethod::Ball,
            PeriodMethod::BallFirstOrder => math::PeriodMethod::BallFirstOrder,
            PeriodMethod::Box => math::PeriodMethod::Box,
        }
    }
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct ReferenceChoice {
    /// The reference point (round-trip decimal at `precision_bits`).
    pub point: Coordinate,
    pub precision_bits: u32,
    pub is_nucleus: bool,
    /// Nucleus period (the orbit then needs only `period` iterations).
    pub period: Option<u64>,
    /// The period the detector reported, also when Newton failed.
    pub detected_period: Option<u64>,
    pub newton_steps: u32,
    /// log2 of the minibrot size estimate (relative to the whole set).
    pub minibrot_size_log2: Option<f64>,
}

/// Picks the reference for a view (nucleus of the lowest-period minibrot in the disc of
/// `radius` around the centre, else the centre). Blocking: call it off the main thread.
#[uniffi::export]
pub fn select_reference(
    re: String,
    im: String,
    radius: String,
    max_iterations: u64,
    precision_bits: u32,
    method: PeriodMethod,
    cancel: Option<Arc<CancelToken>>,
) -> Result<ReferenceChoice, CoreError> {
    let bits = check_bits(precision_bits)?;
    let center = BigComplex::new(parse(&re, bits)?, parse(&im, bits)?);
    let radius = parse(&radius, 64)?;
    let mut is_cancelled = || cancel.as_ref().is_some_and(|c| c.is_cancelled());
    let c = almondbread_core::select_reference(
        &center,
        &radius,
        max_iterations as usize,
        Some(bits),
        method.into(),
        &mut is_cancelled,
    );
    Ok(ReferenceChoice {
        point: Coordinate {
            re: c.point.re.to_string(),
            im: c.point.im.to_string(),
        },
        precision_bits: c.point.precision_bits() as u32,
        is_nucleus: c.is_nucleus,
        period: c.period.map(|p| p as u64),
        detected_period: c.detected_period.map(|p| p as u64),
        newton_steps: c.newton_steps as u32,
        minibrot_size_log2: c.minibrot_size.map(|s| s.log2_magnitude()),
    })
}

/// A computed reference orbit, owned by Rust. Copy it out once per orbit, never per point.
#[derive(uniffi::Object)]
pub struct ReferenceOrbit {
    orbit: almondbread_core::ReferenceOrbit,
}

#[uniffi::export]
impl ReferenceOrbit {
    /// Points Z_0 ... Z_{count-1}.
    pub fn count(&self) -> u64 {
        self.orbit.result.count as u64
    }

    pub fn escaped(&self) -> bool {
        self.orbit.result.escaped
    }

    pub fn cancelled(&self) -> bool {
        self.orbit.result.cancelled
    }

    /// The last point at full precision.
    pub fn final_z(&self, digits: Option<u32>) -> Coordinate {
        let d = digits.map(|d| d.max(1) as usize);
        let z = &self.orbit.result.final_z;
        Coordinate {
            re: z.re.to_decimal_string(d),
            im: z.im.to_decimal_string(d),
        }
    }

    /// The f32 points interleaved (re0, im0, re1, im1, ...): one serialised copy.
    pub fn points_interleaved(&self) -> Vec<f32> {
        self.orbit.points.iter().flatten().copied().collect()
    }

    /// Copies up to `capacity` extended-range points (16-byte `FloatExpComplex`, MSL
    /// `struct { float2 m; int e; }`) to `address`; returns the number copied.
    ///
    /// The caller guarantees `address` is valid for `capacity * 16` writable bytes, aligned to
    /// 8 (e.g. `MTLBuffer.contents()` or an `UnsafeMutableBufferPointer<FloatExpComplex>`),
    /// and not aliased by Rust memory. This is the zero-serialisation path for bulk data.
    pub fn copy_extended_to(&self, address: u64, capacity: u64) -> u64 {
        copy_to(&self.orbit.extended, address, capacity)
    }

    /// Same for the f32 points (8-byte `float2`, alignment 4).
    pub fn copy_points_to(&self, address: u64, capacity: u64) -> u64 {
        copy_to(&self.orbit.points, address, capacity)
    }
}

fn copy_to<T: Copy>(src: &[T], address: u64, capacity: u64) -> u64 {
    let n = src.len().min(capacity as usize);
    if n == 0 || address == 0 {
        return 0;
    }
    let dst = address as usize as *mut T;
    assert!(dst.is_aligned(), "copy destination is not aligned");
    // SAFETY: the caller guarantees `address` points to `capacity` writable, aligned,
    // non-overlapping elements of T (documented on the exported methods); n <= capacity and
    // n <= src.len(). T is plain data (f32 pairs, FloatExpComplex).
    unsafe { std::ptr::copy_nonoverlapping(src.as_ptr(), dst, n) };
    n as u64
}

/// Computes the reference orbit of `re + i im` at `precision_bits` (rounded up to whole
/// limbs) until escape (|Z| > bailout), `max_iterations`, or cancellation. Blocking: call it
/// off the main thread.
#[uniffi::export]
pub fn compute_reference_orbit(
    re: String,
    im: String,
    precision_bits: u32,
    max_iterations: u64,
    bailout: f64,
    cancel: Option<Arc<CancelToken>>,
) -> Result<Arc<ReferenceOrbit>, CoreError> {
    let bits = check_bits(precision_bits)?;
    if max_iterations > MAX_ORBIT_ITERATIONS {
        return Err(invalid(format!("max_iterations must be <= {MAX_ORBIT_ITERATIONS}")));
    }
    if !(bailout.is_finite() && bailout > 0.0) {
        return Err(invalid("bailout must be finite and positive"));
    }
    let c = BigComplex::new(parse(&re, bits)?, parse(&im, bits)?);
    let mut is_cancelled = || cancel.as_ref().is_some_and(|t| t.is_cancelled());
    let mut progress = |done: usize| {
        if let Some(t) = &cancel {
            t.progress.store(done as u64, Ordering::Relaxed);
        }
    };
    let mut control = math::Control {
        check_interval: 4096,
        is_cancelled: &mut is_cancelled,
        progress: &mut progress,
    };
    let orbit = almondbread_core::compute_reference_orbit(&c, bits, max_iterations as usize, bailout, &mut control);
    Ok(Arc::new(ReferenceOrbit { orbit }))
}

/// Size and alignment of `FloatExpComplex` as Rust lays it out (Swift checks it matches).
#[uniffi::export]
pub fn float_exp_complex_layout() -> Vec<u32> {
    vec![
        std::mem::size_of::<FloatExpComplex>() as u32,
        std::mem::align_of::<FloatExpComplex>() as u32,
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn api_round_trip() {
        assert!(core_version().starts_with("almondbread-core "));
        let c = normalize_coordinate("-0.75".into(), "0.1".into(), 128, Some(5)).unwrap();
        assert_eq!(
            c,
            Coordinate {
                re: "-0.75".into(),
                im: "0.1".into()
            }
        );
        assert!(matches!(
            normalize_coordinate("x".into(), "0".into(), 64, None),
            Err(CoreError::Malformed { .. })
        ));
        let o = compute_reference_orbit("-0.1".into(), "0.1".into(), 128, 1000, 2.0, None).unwrap();
        assert_eq!(o.count(), 1001);
        let mut buf = vec![FloatExpComplex::ZERO; 1001];
        assert_eq!(o.copy_extended_to(buf.as_mut_ptr() as u64, 1001), 1001);
        assert_eq!(buf[1].exponent, -3); // Z_1 = C = -0.1 + 0.1i
        let token = CancelToken::new();
        token.cancel();
        let o = compute_reference_orbit("-0.1".into(), "0.1".into(), 128, 100_000, 2.0, Some(token)).unwrap();
        assert!(o.cancelled() && o.count() == 4097);
        let r = select_reference(
            "-1.752".into(),
            "0.0005".into(),
            "0.01".into(),
            1000,
            128,
            PeriodMethod::Ball,
            None,
        )
        .unwrap();
        assert!(r.is_nucleus && r.period == Some(3));
    }
}
